schemas.schema-01-systematic.prisma:
/// Represents a communication channel in the system.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model channels {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Name of the channel.
  name String

  /// Description of the channel.
  description String?

  //----
  // RELATIONS
  //----
  sections sections[]
}

/// Represents a section within a channel.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model sections {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Foreign key referencing the Channels table.
  channel_id String @db.Uuid

  /// Name of the section.
  name String

  /// Description of the section.
  description String?

  //----
  // RELATIONS
  //----
  channel channels @relation(fields: [channel_id], references: [id], onDelete: Cascade)

  @@index([channel_id])
}

/// Represents system configurations.
///
/// @namespace Systematic
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model configurations {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Configuration key.
  key String

  /// Configuration value.
  value String

  //----
  // RELATIONS
  //----
  @@unique([key])
}

schemas.schema-02-actors.prisma:
/// User accounts for authentication and authorization
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model users {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// User's email address for login and notifications.
  email String

  /// Hashed password for secure authentication.
  password_hash String

  //----
  // RELATIONS
  //----
  user_sessions user_sessions[]

  @@unique([email])
}

/// Session data for authenticated users
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model user_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// References the Users table.
  user_id String @db.Uuid

  /// User's IP address.
  ip String

  /// Session URL.
  href String

  /// Referrer URL.
  referrer String

  /// Session creation time.
  created_at DateTime @db.Timestamptz

  /// Session expiration time.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  user users @relation(fields: [user_id], references: [id], onDelete: Cascade)

  @@index([user_id, created_at])
}

/// Administrator accounts for system management
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model administrators {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// Administrator's email for login and notifications.
  email String

  //----
  // RELATIONS
  //----
  administrator_sessions administrator_sessions[]

  @@unique([email])
}

/// Session data for administrators
///
/// @namespace Actors
/// @author AutoBE - https://github.com/wrtnlabs/autobe
model administrator_sessions {
  //----
  // COLUMNS
  //----
  /// Primary Key.
  id String @id @db.Uuid

  /// References the Administrators table.
  administrator_id String @db.Uuid

  /// Administrator's IP address.
  ip String

  /// Session URL.
  href String

  /// Referrer URL.
  referrer String

  /// Session creation time.
  created_at DateTime @db.Timestamptz

  /// Session expiration time.
  expired_at DateTime? @db.Timestamptz

  //----
  // RELATIONS
  //----
  administrator administrators @relation(fields: [administrator_id], references: [id], onDelete: Cascade)

  @@index([administrator_id, created_at])
}

